
.inventory-panel {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.section-title {
  font-size: 0.82rem;
  font-weight: 700;
  color: var(--accent-purple);
  border-bottom: 1px solid var(--border-main);
  padding-bottom: 3px;
}

.item-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.item-row {
  display: flex;
  align-items: center;
  background: var(--bg-section);
  border: 1px solid var(--border-main);
  padding: 6px 8px;
  gap: 8px;
  transition:
    border-color 0.2s,
    transform 0.15s;
}

.item-row:hover {
  border-color: var(--accent-purple);
  transform: translateX(3px);
}

.item-icon {
  font-size: 1.1rem;
  width: 28px;
  text-align: center;
  flex-shrink: 0;
}

.item-info {
  flex: 1;
  min-width: 0;
}

.item-name {
  display: block;
  font-weight: 600;
  font-size: 0.8rem;
  color: var(--text-primary);
}

.item-desc {
  display: block;
  font-size: 0.68rem;
  color: var(--text-dim);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.item-qty {
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 0.78rem;
  color: var(--accent-gold);
  flex-shrink: 0;
}

.empty-state {
  text-align: center;
  padding: 20px;
}

.empty-icon {
  font-size: 1.8rem;
  opacity: 0.4;
  margin-bottom: 6px;
}

.empty-text {
  color: var(--text-dim);
  font-size: 0.82rem;
}
