
.npc-panel {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.section-title {
  font-size: 0.82rem;
  font-weight: 700;
  color: var(--accent-purple);
  border-bottom: 1px solid var(--border-main);
  padding-bottom: 3px;
  margin-top: 4px;
}

.info-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 3px;
}

.info-grid.compact {
  grid-template-columns: repeat(3, 1fr);
}

.field {
  background: var(--bg-section);
  padding: 3px 6px;
  border: 1px solid var(--border-main);
  font-size: 0.7rem;
  overflow: hidden;
}

.field.full {
  grid-column: 1 / -1;
}

.k {
  display: block;
  color: var(--text-dim);
  font-size: 0.62rem;
  margin-bottom: 1px;
}

.v {
  color: var(--text-primary);
  word-break: break-all;
}
.v.highlight {
  color: var(--accent-gold);
  font-weight: 600;
}
.v.accent {
  color: var(--accent-pink);
}
.v.warn {
  color: var(--accent-red);
}

.pair-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3px;
}

.pair {
  background: var(--bg-section);
  padding: 4px 6px;
  border: 1px solid var(--border-main);
  font-size: 0.72rem;
}

.pair-label {
  display: block;
  color: var(--text-dim);
  font-size: 0.62rem;
}
.pair-val {
  color: var(--text-primary);
}
.pair-val.accent {
  color: var(--accent-pink);
}

.empty-state {
  text-align: center;
  padding: 24px 12px;
}
.empty-icon {
  font-size: 2rem;
  margin-bottom: 8px;
  opacity: 0.5;
}
.empty-text {
  color: var(--text-secondary);
  font-size: 0.9rem;
  margin-bottom: 4px;
}
.empty-hint {
  color: var(--text-dim);
  font-size: 0.72rem;
}

@media (max-width: 400px) {
  .info-grid,
  .info-grid.compact {
    grid-template-columns: repeat(2, 1fr);
  }
  .pair-grid {
    grid-template-columns: 1fr;
  }
}
