
.char-library {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.section-title {
  font-size: 0.82rem;
  font-weight: 700;
  color: var(--accent-purple);
  border-bottom: 1px solid var(--border-main);
  padding-bottom: 3px;
}

.create-title {
  margin-top: 6px;
}

/* 角色列表 */
.char-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.char-card {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: var(--bg-section);
  border: 1px solid var(--border-main);
  padding: 8px 10px;
  cursor: pointer;
  transition: all 0.2s;
}

.char-card:hover {
  border-color: var(--accent-purple);
  transform: translateX(3px);
}

.char-card.active {
  border-color: var(--accent-gold);
  background: rgba(212, 160, 23, 0.1);
}

.char-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.char-name {
  font-weight: 700;
  font-size: 0.85rem;
}
.char-tags {
  font-size: 0.68rem;
  color: var(--text-dim);
}

.char-score {
  text-align: right;
}
.score-label {
  display: block;
  font-size: 0.6rem;
  color: var(--text-dim);
}
.score-val {
  font-weight: 700;
  font-size: 0.8rem;
  color: var(--accent-gold);
}

.empty-hint {
  text-align: center;
  padding: 12px;
  font-size: 0.78rem;
  color: var(--text-dim);
}

/* 创建表单 */
.form-hint {
  font-size: 0.68rem;
  color: var(--text-dim);
  text-align: center;
  padding: 3px;
  border: 1px dashed var(--border-main);
  background: rgba(155, 89, 182, 0.05);
}

.form-section {
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.form-label {
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--accent-purple);
}

.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3px;
}

.ff {
  display: flex;
  flex-direction: column;
  gap: 1px;
}
.ff.wide {
  grid-column: 1 / -1;
}

.ff label {
  font-size: 0.6rem;
  color: var(--text-dim);
  font-weight: 600;
}

.ff input,
.ff select,
.ff textarea {
  background: var(--bg-section);
  border: 1px solid var(--border-main);
  padding: 4px 6px;
  color: var(--text-primary);
  font-family: var(--font-main);
  font-size: 0.72rem;
  outline: none;
  transition: border-color 0.2s;
  width: 100%;
}

.ff input:focus,
.ff select:focus,
.ff textarea:focus {
  border-color: var(--accent-purple);
}
.ff input::placeholder,
.ff textarea::placeholder {
  color: var(--text-dim);
  opacity: 0.6;
}
.ff textarea {
  resize: vertical;
  min-height: 32px;
}

.gen-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 10px;
  background: linear-gradient(135deg, rgba(155, 89, 182, 0.3), rgba(107, 63, 160, 0.4));
  border: 1px solid var(--accent-purple);
  color: var(--text-primary);
  font-family: var(--font-main);
  font-size: 0.85rem;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.2s;
}

.gen-btn:hover:not(:disabled) {
  background: linear-gradient(135deg, rgba(155, 89, 182, 0.5), rgba(107, 63, 160, 0.55));
  transform: translateY(-1px);
}

.gen-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.rand-btn {
  padding: 7px;
  background: var(--bg-section);
  border: 1px dashed var(--border-main);
  color: var(--text-secondary);
  font-family: var(--font-main);
  font-size: 0.72rem;
  cursor: pointer;
  transition: all 0.2s;
}

.rand-btn:hover:not(:disabled) {
  border-color: var(--accent-gold);
  color: var(--accent-gold);
}
.rand-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  background: var(--accent-purple);
  border-radius: 50%;
  animation: pulse 1s infinite;
}

@keyframes pulse {
  0%,
  100% {
    opacity: 1;
    transform: scale(1);
  }
  50% {
    opacity: 0.4;
    transform: scale(0.7);
  }
}

@media (max-width: 360px) {
  .form-grid {
    grid-template-columns: 1fr;
  }
  .ff.wide {
    grid-column: 1;
  }
}
