
.hero-stats {
  padding: 10px 12px;
  background: var(--bg-card);
  border-bottom: 1px solid var(--border-main);
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.stat-row {
  display: flex;
  gap: 10px;
  align-items: center;
}

.stat-block {
  display: flex;
  align-items: center;
  gap: 6px;
}

.stat-block.bar-block {
  flex: 1;
}

.stat-block.full {
  width: 100%;
}

.label {
  font-size: 0.78rem;
  color: var(--text-secondary);
  white-space: nowrap;
  small {
    color: var(--text-dim);
    font-size: 0.68rem;
  }
}

.value {
  font-weight: 700;
  font-size: 0.9rem;
  color: var(--accent-gold);
  font-family: var(--font-mono);
}

.bar-wrap {
  flex: 1;
  height: 8px;
  background: var(--bar-bg);
  border: 1px solid var(--border-main);
  border-radius: 4px;
  overflow: hidden;
}

.bar-fill {
  height: 100%;
  border-radius: 4px;
  transition: width 0.4s ease;
}

.bar-fill.holy {
  background: linear-gradient(90deg, var(--accent-gold), #f1c40f);
}

.bar-fill.mp {
  background: linear-gradient(90deg, var(--bar-fill-mp), var(--accent-purple));
}

.bar-val {
  font-size: 0.7rem;
  font-family: var(--font-mono);
  color: var(--text-dim);
  white-space: nowrap;
}

.info-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 4px;
}

.info-item {
  background: var(--bg-section);
  padding: 4px 6px;
  border: 1px solid var(--border-main);
  font-size: 0.72rem;
  display: flex;
  flex-direction: column;
}

.info-label {
  color: var(--text-dim);
  font-size: 0.65rem;
  margin-bottom: 1px;
}

.info-val {
  color: var(--text-primary);
  word-break: break-all;
}

.wealth-row {
  display: flex;
  gap: 8px;
  justify-content: center;
  padding: 4px 0;
}

.wealth-item {
  font-size: 0.78rem;
  font-family: var(--font-mono);
  font-weight: 600;
}

.wealth-item.purple {
  color: #a855f7;
}
.wealth-item.gold {
  color: var(--accent-gold);
}
.wealth-item.silver {
  color: #bdc3c7;
}
.wealth-item.copper {
  color: #cd7f32;
}

.location-row {
  font-size: 0.75rem;
  color: var(--text-secondary);
  text-align: center;
  padding: 2px 0;
  border-top: 1px dashed var(--border-main);
}

@media (max-width: 400px) {
  .info-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .stat-row {
    flex-direction: column;
    align-items: stretch;
  }
}
